    public static int hoare(int[] v, int ini, int fim) {
        int pivot = v[ini];
        int i = ini - 1;
        int j = fim + 1;

        while (true) {
            do {
                i += 1;
            } while (v[i] < pivot);

            do {
                j -= 1;
            } while (v[j] >= pivot); // Changed > to >=

            if (i < j) {
                int tmp = v[i];
                v[i] = v[j];
                v[j] = tmp;
            } else {
                return j + 1;
            }

        }

